{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-07",
  "sketch": {
    "components": ["Checkout browser client", "Discount code logic (client-side)", "Order API", "Payment service"],
    "dataStores": ["Orders", "Discount codes"],
